How to use fixtures¶ > “Requesting” fixtures¶ > Quick example¶
Quick example¶

import pytest

class Fruit:
def __init__(self, name):
self.name = name
self.cubed = False

def cube(self):
self.cubed = True

class FruitSalad:
def __init__(self, *fruit_bowl):
self.fruit = fruit_bowl
self._cube_fruit()

def _cube_fruit(self):
for fruit in self.fruit:
fruit.cube()

# Arrange
@pytest.fixture
def fruit_bowl():
return [Fruit("apple"), Fruit("banana")]

def test_fruit_salad(fruit_bowl):
# Act
fruit_salad = FruitSalad(*fruit_bowl)

How to use fixtures¶ > “Requesting” fixtures¶ > A test/fixture can request more than one fixture at a time¶
A test/fixture can request more than one fixture at a time¶

Tests and fixtures aren’t limited to requesting a single fixture at a time.
They can request as many as they like. Here’s another quick example to
demonstrate:

# contents of test_append.py
import pytest

# Arrange
@pytest.fixture
def first_entry():
return "a"

# Arrange
@pytest.fixture
def second_entry():
return 2

# Arrange
@pytest.fixture
def order(first_entry, second_entry):
return [first_entry, second_entry]

# Arrange
@pytest.fixture
def expected_list():
return ["a", 2, 3.0]

def test_string(order, expected_list):
# Act
order.append(3.0)

# Assert
assert order == expected_list

